import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import Index from '@/pages/Index';
import Variant1Spec from '@/variants/Variant1';
import Variant2Spec from '@/variants/Variant2';
import Variant3Spec from '@/variants/Variant3';
import Variant4Spec from '@/variants/Variant4';
import Variant5Spec from '@/variants/Variant5';

const router = createBrowserRouter([
  {
    path: '/',
    element: <Index />,
  },
  {
    path: '/variant-1',
    element: <Variant1Spec />,
  },
  {
    path: '/variant-2',
    element: <Variant2Spec />,
  },
  {
    path: '/variant-3',
    element: <Variant3Spec />,
  },
  {
    path: '/variant-4',
    element: <Variant4Spec />,
  },
  {
    path: '/variant-5',
    element: <Variant5Spec />,
  },
]);

export default function App() {
  return <RouterProvider router={router} />;
}

