import type { Product, BundleSize } from "@/lib/types";

export const VELA_PRODUCT: Product = {
  id: "vela-focus-formula",
  name: "Vela Focus Formula",
  slug: "vela-focus-formula",
  format: "capsules",
  servingsPerBottle: 30,
  servingSize: "2 capsules",
  priceOnetime: 79,
  priceSubscribe: 67,
  bundleMultipliers: { 1: 1, 2: 1.92, 3: 2.55 },
  bundleSavings: { 1: 0, 2: 8, 3: 15 },
  freeShippingThreshold: 50,
};

export function calcUnitPrice(
  product: Product,
  purchaseType: "one-time" | "subscribe",
  bundle: BundleSize,
): number {
  const base =
    purchaseType === "subscribe" ? product.priceSubscribe : product.priceOnetime;
  const multiplier = product.bundleMultipliers[bundle];
  return Math.round((base * multiplier) / bundle * 100) / 100;
}

export function calcTotalPrice(
  product: Product,
  purchaseType: "one-time" | "subscribe",
  bundle: BundleSize,
): number {
  const base =
    purchaseType === "subscribe" ? product.priceSubscribe : product.priceOnetime;
  const multiplier = product.bundleMultipliers[bundle];
  return Math.round(base * multiplier * 100) / 100;
}

export const PRESS_LOGOS: ReadonlyArray<string> = [
  "Wired",
  "Bloomberg",
  "Outside",
  "GQ",
  "Forbes",
  "The Verge",
];

