import { useCallback, useMemo, useState } from "react";
import type { CartState, CartActions, BundleSize, PurchaseType } from "@/lib/types";
import { VELA_PRODUCT, calcUnitPrice, calcTotalPrice } from "@/data/mock";

export function useCartState(): CartState & CartActions {
  const [purchaseType, setPurchaseType] = useState<PurchaseType>("subscribe");
  const [bundle, setBundle] = useState<BundleSize>(1);
  const [cartOpen, setCartOpen] = useState<boolean>(false);

  const unitPrice = useMemo(
    () => calcUnitPrice(VELA_PRODUCT, purchaseType, bundle),
    [purchaseType, bundle],
  );
  const totalPrice = useMemo(
    () => calcTotalPrice(VELA_PRODUCT, purchaseType, bundle),
    [purchaseType, bundle],
  );

  const openCart = useCallback(() => setCartOpen(true), []);
  const closeCart = useCallback(() => setCartOpen(false), []);
  const toggleCart = useCallback(() => setCartOpen((v) => !v), []);

  return {
    purchaseType,
    bundle,
    cartOpen,
    unitPrice,
    totalPrice,
    setPurchaseType,
    setBundle,
    openCart,
    closeCart,
    toggleCart,
  };
}

