import { Link } from "react-router-dom";
import { ShoppingBag, Menu } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useCart } from "@/components/shared/cart-context";
import { cn } from "@/lib/utils";

interface NavProps {
  variant?: "cream" | "forest";
  showVariantPicker?: boolean;
}

export function Nav({ variant = "cream", showVariantPicker = true }: NavProps) {
  const { openCart } = useCart();
  const isForest = variant === "forest";
  return (
    <nav
      className={cn(
        "sticky top-0 z-30 w-full border-b backdrop-blur-md",
        isForest
          ? "border-white/10 bg-forest-950/80 text-cream-50"
          : "border-cream-300 bg-cream-50/85 text-ink-900",
      )}
    >
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-6">
        <Link to="/" className="flex items-center gap-2 font-display text-2xl font-semibold tracking-tight">
          <span className={cn("inline-block h-2 w-2 rounded-full", isForest ? "bg-amber-400" : "bg-amber-500")} />
          Vela
        </Link>
        <div className="hidden items-center gap-8 md:flex">
          <a href="#science" className="text-sm font-medium hover:opacity-80">Science</a>
          <a href="#ingredients" className="text-sm font-medium hover:opacity-80">Ingredients</a>
          <a href="#reviews" className="text-sm font-medium hover:opacity-80">Reviews</a>
          <a href="#faq" className="text-sm font-medium hover:opacity-80">FAQ</a>
          {showVariantPicker && (
            <Link to="/" className="text-sm font-medium opacity-70 hover:opacity-100">
              Variants ↗
            </Link>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Button
            onClick={openCart}
            variant={isForest ? "secondary" : "outline"}
            size="sm"
            className="gap-2"
            aria-label="Open cart"
          >
            <ShoppingBag className="size-4" />
            <span className="hidden sm:inline">Cart</span>
          </Button>
          <Button variant="ghost" size="icon" className="md:hidden" aria-label="Menu">
            <Menu className="size-5" />
          </Button>
        </div>
      </div>
    </nav>
  );
}

