import { useCart } from "@/components/shared/cart-context";
import { VELA_PRODUCT } from "@/data/mock";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import type { BundleSize } from "@/lib/types";

const OPTIONS: ReadonlyArray<{ size: BundleSize; label: string; popular?: boolean }> = [
  { size: 1, label: "1 Bottle" },
  { size: 2, label: "2 Bottles", popular: true },
  { size: 3, label: "3 Bottles" },
];

export function BundleSelector() {
  const { bundle, setBundle, purchaseType } = useCart();
  const base =
    purchaseType === "subscribe"
      ? VELA_PRODUCT.priceSubscribe
      : VELA_PRODUCT.priceOnetime;

  return (
    <div className="space-y-2">
      <p className="font-mono text-xs uppercase tracking-wider text-ink-500">
        Choose your supply
      </p>
      <div className="grid grid-cols-3 gap-2">
        {OPTIONS.map((opt) => {
          const perBottle = (base * VELA_PRODUCT.bundleMultipliers[opt.size]) / opt.size;
          const savings = VELA_PRODUCT.bundleSavings[opt.size];
          const active = bundle === opt.size;
          return (
            <button
              key={opt.size}
              type="button"
              onClick={() => setBundle(opt.size)}
              className={cn(
                "relative flex flex-col items-start gap-1 rounded-lg border-2 p-3 text-left transition-[border-color,background-color,transform] duration-200 ease-[var(--ease-out)]",
                active
                  ? "border-forest-800 bg-cream-100 -translate-y-0.5"
                  : "border-cream-300 bg-cream-50 hover:border-forest-400",
              )}
              aria-pressed={active}
            >
              {opt.popular && (
                <Badge
                  variant="secondary"
                  className="absolute -top-2 right-2 bg-amber-500 text-forest-950 hover:bg-amber-500"
                >
                  Most popular
                </Badge>
              )}
              <span className="text-sm font-semibold text-forest-950">{opt.label}</span>
              <span className="font-mono text-xs text-ink-600">
                ${perBottle.toFixed(2)}/bottle
              </span>
              {savings > 0 ? (
                <span className="font-mono text-xs text-forest-700">
                  Save {savings}%
                </span>
              ) : (
                <span className="font-mono text-xs text-ink-400">—</span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

