import { useCart } from "@/components/shared/cart-context";
import { VELA_PRODUCT } from "@/data/mock";
import { cn } from "@/lib/utils";

export function PriceLine({ className }: { className?: string }) {
  const { purchaseType, bundle, totalPrice } = useCart();
  const oneTimeRef = VELA_PRODUCT.priceOnetime * bundle;
  const showCompare = purchaseType === "subscribe" || bundle > 1;
  return (
    <div className={cn("flex items-baseline gap-3", className)}>
      <span className="font-display text-3xl font-semibold tabular-nums text-forest-950">
        ${totalPrice.toFixed(2)}
