import { useEffect, useRef, useState, type RefObject } from "react";
import { Button } from "@/components/ui/button";
import { useCart } from "@/components/shared/cart-context";
import { cn } from "@/lib/utils";

interface StickyAddToCartProps {
  heroRef: RefObject<HTMLElement | null>;
  productName?: string;
}

export function StickyAddToCart({ heroRef, productName = "Vela Focus Formula" }: StickyAddToCartProps) {
  const { totalPrice, openCart } = useCart();
  const [visible, setVisible] = useState(false);
  const observerRef = useRef<IntersectionObserver | null>(null);

  useEffect(() => {
    const el = heroRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    observerRef.current = new IntersectionObserver(
      ([entry]) => {
        if (!entry) return;
        setVisible(!entry.isIntersecting);
      },
      { threshold: 0, rootMargin: "-80px 0px 0px 0px" },
    );
    observerRef.current.observe(el);
    return () => observerRef.current?.disconnect();
  }, [heroRef]);

  return (
    <div
      className={cn(
        "fixed inset-x-0 bottom-0 z-40 border-t border-cream-300 bg-cream-50/95 px-4 py-3 backdrop-blur-md md:hidden",
        "transition-[opacity,transform] duration-[var(--duration-base)] ease-[var(--ease-out)]",
        visible ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-full opacity-0",
      )}
      aria-hidden={!visible}
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex flex-col">
          <span className="text-sm font-semibold text-forest-950">{productName}</span>
          <span className="font-mono text-xs text-ink-600 tabular-nums">
            ${totalPrice.toFixed(2)}
          </span>
        </div>
        <Button onClick={openCart} className="bg-forest-800 text-cream-50 hover:bg-forest-900">
          Add to cart
        </Button>
      </div>
    </div>
  );
}

