import { pageCopy } from "@/data/page-copy";
import { ShieldCheck, FlaskConical, Award, BadgeCheck } from "lucide-react";
import { cn } from "@/lib/utils";

const ICONS = {
  NSF: ShieldCheck,
  INFORMED: BadgeCheck,
  "BATCH-TESTED": FlaskConical,
  cGMP: Award,
} as const;

interface TrustBarProps {
  variant?: "cream" | "forest";
  compact?: boolean;
}

export function TrustBar({ variant = "cream", compact = false }: TrustBarProps) {
  const isForest = variant === "forest";
  return (
    <section
      aria-label="Certifications"
      className={cn(
        "border-y",
        isForest ? "border-white/10 bg-forest-900/40" : "border-cream-300 bg-cream-100",
        compact ? "py-4" : "py-8",
      )}
    >
      <div className="mx-auto max-w-7xl px-6">
        <div className={cn("grid gap-6", compact ? "grid-cols-2 md:grid-cols-4" : "md:grid-cols-4")}>
          {pageCopy.trust.map((item) => {
            const Icon = ICONS[item.badge as keyof typeof ICONS] ?? ShieldCheck;
            return (
              <div key={item.badge} className="flex items-start gap-3">
                <div
                  className={cn(
                    "flex size-10 shrink-0 items-center justify-center rounded-md",
                    isForest ? "bg-amber-400/10 text-amber-300" : "bg-amber-100 text-amber-800",
                  )}
                >
                  <Icon className="size-5" />
                </div>
                <div className="min-w-0">
                  <p
                    className={cn(
                      "font-mono text-[10px] uppercase tracking-wider",
                      isForest ? "text-cream-300" : "text-ink-500",
                    )}
                  >
                    {item.badge}
                  </p>
                  <p
                    className={cn(
                      "text-sm font-semibold",
                      isForest ? "text-cream-50" : "text-forest-950",
                    )}
                  >
                    {item.name}
                  </p>
                  {!compact && (
                    <p
                      className={cn(
                        "mt-1 text-xs leading-relaxed",
                        isForest ? "text-cream-400" : "text-ink-600",
                      )}
                    >
                      {item.description}
                    </p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

