import { pageCopy } from "@/data/page-copy";
import { Star } from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";

export function ReviewsSection() {
  const { reviews, reviewSummary } = pageCopy;
  const [tab, setTab] = useState<"helpful" | "recent">("helpful");
  const total = reviewSummary.totalReviews;

  return (
    <section id="reviews" className="bg-cream-100 py-24">
      <div className="mx-auto max-w-6xl px-6">
        <div className="mb-12 grid gap-10 md:grid-cols-[2fr_3fr]">
          <div>
            <p className="font-mono text-xs uppercase tracking-wider text-amber-700">
              Verified reviews
            </p>
            <h2 className="mt-2 font-display text-4xl font-semibold tracking-tight text-forest-950 md:text-5xl">
              847 buyers. One bottle each.
            </h2>
            <div className="mt-6 flex items-end gap-3">
              <span className="font-display text-6xl font-semibold tabular-nums text-forest-950">
                {reviewSummary.averageRating}
              </span>
              <div className="mb-2 flex flex-col gap-1">
                <div className="flex gap-0.5">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <Star key={n} className="size-4 fill-amber-500 text-amber-500" />
                  ))}
                </div>
                <span className="text-xs text-ink-600">
                  {reviewSummary.wouldRecommend}% would recommend
                </span>
              </div>
            </div>
          </div>

          <div className="space-y-2.5">
            {[5, 4, 3, 2, 1].map((star) => {
              const count = reviewSummary.distribution[star as 1 | 2 | 3 | 4 | 5];
              const pct = (count / total) * 100;
              return (
                <div key={star} className="flex items-center gap-3 text-sm">
                  <span className="flex w-8 items-center gap-0.5 font-mono text-xs text-ink-600 tabular-nums">
                    {star}
                    <Star className="size-3 fill-amber-500 text-amber-500" />
                  </span>
                  <div className="h-2 flex-1 overflow-hidden rounded-full bg-cream-300">
                    <div
                      className="h-full rounded-full bg-forest-700 transition-[width] duration-[var(--duration-slow)] ease-[var(--ease-out)]"
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                  <span className="w-12 text-right font-mono text-xs text-ink-500 tabular-nums">
                    {count}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

        <div className="mb-6 flex gap-1 rounded-lg border border-cream-300 bg-cream-50 p-1">
          {(["helpful", "recent"] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTab(t)}
              className={cn(
                "flex-1 rounded-md px-3 py-1.5 text-xs font-medium transition-colors",
                tab === t
                  ? "bg-forest-800 text-cream-50"
                  : "text-ink-600 hover:text-forest-800",
              )}
            >
              {t === "helpful" ? "Most helpful" : "Most recent"}
            </button>
          ))}
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          {reviews.map((r) => (
            <article
              key={r.title}
              className="flex flex-col gap-3 rounded-xl border border-cream-300 bg-cream-50 p-5"
            >
              <div className="flex items-center justify-between gap-2">
                <div className="flex gap-0.5">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <Star
                      key={n}
                      className={cn(
                        "size-3.5",
                        n <= r.rating
                          ? "fill-amber-500 text-amber-500"
                          : "fill-cream-300 text-cream-300",
                      )}
                    />
                  ))}
                </div>
                <span className="rounded-full bg-forest-50 px-2 py-0.5 font-mono text-[10px] uppercase tracking-wider text-forest-800">
                  Verified · day {r.daysOnVela}
                </span>
              </div>
              <h4 className="font-display text-lg font-semibold tracking-tight text-forest-950">
                {r.title}
              </h4>
              <p className="text-sm leading-relaxed text-ink-700">{r.body}</p>
              <p className="mt-auto font-mono text-xs uppercase tracking-wider text-ink-500">
                {r.author} — {new Date(r.date).toLocaleDateString("en-US", { month: "short", year: "numeric" })}
              </p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

