          </h2>
        </div>

        <Accordion
          type="single"
          collapsible
          onValueChange={(v) => v && setOpenCount((n) => n + 1)}
          className="overflow-hidden rounded-xl border border-cream-300 bg-cream-100"
        >
          {faq.map((q, idx) => (
            <AccordionItem
              key={q.question}
              value={`faq-${idx}`}
              className="border-cream-300 last:border-b-0"
            >
              <AccordionTrigger className="px-6 py-5 text-left text-base font-semibold text-forest-950 hover:no-underline">
                {q.question}
              </AccordionTrigger>
              <AccordionContent className="px-6 pb-5 text-sm leading-relaxed text-ink-700">
                {q.answer}
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>

        {openCount >= 3 && (
          <div className="mt-6 rounded-xl border border-amber-200 bg-amber-50 p-5 text-center">
            <p className="font-display text-xl font-semibold text-forest-950">
              Still considering?
            </p>
            <p className="mt-1 text-sm text-ink-700">
              Read the full label before you decide.
            </p>
            <Button variant="outline" className="mt-4 border-forest-800 text-forest-800 hover:bg-forest-50">
              View full label
            </Button>
          </div>
        )}
      </div>
    </section>
  );
}

