import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { useEffect, useState } from "react";
import { useCart } from "@/components/shared/cart-context";
import { FlaskConical } from "lucide-react";

const SESSION_KEY = "vela-exit-intent-shown";

export function ExitIntent() {
  const { cartOpen } = useCart();
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (window.matchMedia("(max-width: 768px)").matches) return;
    if (sessionStorage.getItem(SESSION_KEY)) return;

    const handler = (e: MouseEvent) => {
      if (e.clientY <= 0 && !cartOpen) {
        setOpen(true);
        sessionStorage.setItem(SESSION_KEY, "1");
        document.removeEventListener("mouseleave", handler);
      }
    };
    document.addEventListener("mouseleave", handler);
    return () => document.removeEventListener("mouseleave", handler);
  }, [cartOpen]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="max-w-md border-cream-300 bg-cream-50 sm:max-w-md">
        <div className="flex flex-col items-center text-center">
          <div className="mb-4 flex size-12 items-center justify-center rounded-full bg-amber-100 text-amber-800">
            <FlaskConical className="size-6" />
          </div>
          <DialogTitle className="font-display text-2xl font-semibold tracking-tight text-forest-950">
            One more thing.
          </DialogTitle>
          <p className="mt-2 text-sm leading-relaxed text-ink-700">
            See the full ingredient label before you decide. Every active. Every dose. Every excipient.
          </p>
          <div className="mt-6 flex w-full flex-col gap-2">
            <Button
              onClick={() => {
                setOpen(false);
                document.getElementById("ingredients")?.scrollIntoView({ behavior: "smooth" });
              }}
              className="w-full bg-forest-800 text-cream-50 hover:bg-forest-900"
            >
              View label
            </Button>
            <Button
              variant="ghost"
              onClick={() => setOpen(false)}
              className="text-xs text-ink-500 hover:text-ink-700"
            >
              No thanks
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

