import { Button } from "@/components/ui/button";
import { useCart } from "@/components/shared/cart-context";
import { pageCopy } from "@/data/page-copy";
import { ArrowRight } from "lucide-react";

interface CTABlockProps {
  variant?: "primary" | "transparency" | "subscription";
  theme?: "cream" | "forest";
}

export function CTABlock({ variant = "primary", theme = "cream" }: CTABlockProps) {
  const { openCart } = useCart();
  const block = pageCopy.ctaBlocks[variant];
  const isForest = theme === "forest";

  return (
    <section
      className={
        isForest
          ? "bg-gradient-to-b from-forest-900 to-forest-950 py-24 text-cream-50"
          : "bg-gradient-to-b from-cream-100 to-cream-200 py-24 text-forest-950"
      }
    >
      <div className="mx-auto max-w-3xl px-6 text-center">
        <h2 className="font-display text-4xl font-semibold tracking-tight md:text-5xl">
          {block.headline}
        </h2>
        <p
          className={
            "mt-4 text-base leading-relaxed " + (isForest ? "text-cream-300" : "text-ink-700")
          }
        >
          {block.body}
        </p>
        <div className="mt-8 flex flex-col items-center justify-center gap-3 sm:flex-row">
          <Button
            onClick={openCart}
            size="lg"
            className="gap-2 bg-amber-500 text-forest-950 hover:bg-amber-400"
          >
            {block.ctaPrimary}
            <ArrowRight className="size-4" />
          </Button>
          <Button
            variant={isForest ? "outline" : "outline"}
            size="lg"
            className={
              isForest
                ? "border-cream-50/30 text-cream-50 hover:bg-cream-50/10"
                : "border-forest-800 text-forest-800 hover:bg-cream-50"
            }
          >
            {block.ctaSecondary}
          </Button>
        </div>
      </div>
    </section>
  );
}

